function CompareModal({lots,onClose}){
  if(!lots.length)return null;
  const fields=[["gov","المحافظة"],["dist","المديرية"],["village","القرية"],["basin","الحوض"],["plot","رقم القطعة"],["plotKey","مفتاح القطعة"],["area","المساحة (م²)"],["adminPrice","السعر الإداري"],["owner","المالك"],["share","الحصة"]];
  return <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.6)",backdropFilter:"blur(4px)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
    <div onClick={e=>e.stopPropagation()} style={{background:"white",borderRadius:20,maxWidth:Math.min(lots.length*220+200,900),width:"100%",maxHeight:"90vh",overflow:"auto",boxShadow:"0 25px 50px rgba(0,0,0,0.25)"}}>
      <div style={{padding:"20px 24px",borderBottom:"1px solid #e2e8f0",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <h2 style={{fontSize:18,fontWeight:800,color:"#1e293b"}}>⚖️ مقارنة ({lots.length})</h2>
        <button onClick={onClose} style={{background:"#f1f5f9",border:"none",borderRadius:8,width:32,height:32,cursor:"pointer",fontSize:14}}>✕</button>
      </div>
      <div style={{overflow:"auto",padding:"16px 24px 24px"}}>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
          <thead><tr>
            <th style={{textAlign:"right",padding:"8px 10px",background:"#f8fafc",borderBottom:"2px solid #e2e8f0",fontWeight:700,color:"#64748b",position:"sticky",right:0,minWidth:110,zIndex:1}}>البيان</th>
            {lots.map(l=><th key={l.id} style={{textAlign:"center",padding:"8px 10px",background:"#f8fafc",borderBottom:"2px solid #e2e8f0",fontWeight:800,color:"#1e293b",minWidth:130}}>قطعة {l.plot}<br/><span style={{fontSize:10,fontWeight:500,color:"#64748b"}}>{l.village}</span></th>)}
          </tr></thead>
          <tbody>{fields.map(([f,label],i)=>{
            const isNum=f==="area";
            const vals=lots.map(l=>l[f]);
            const best=isNum?Math.max(...vals.filter(v=>typeof v==="number"&&v>0)):null;
            return <tr key={f} style={{background:i%2===0?"white":"#fafafa"}}>
              <td style={{padding:"8px 10px",fontWeight:600,color:"#64748b",borderBottom:"1px solid #f1f5f9",position:"sticky",right:0,background:i%2===0?"white":"#fafafa",zIndex:1}}>{label}</td>
              {lots.map(l=>{
                const v=l[f];const isBest=isNum&&v===best&&v>0;
                return <td key={l.id} style={{padding:"8px 10px",textAlign:"center",borderBottom:"1px solid #f1f5f9",fontWeight:isBest?800:500,color:isBest?"#059669":"#1e293b",background:isBest?"#f0fdf4":"transparent"}}>
                  {f==="area"?fmt(v)+" م²":String(v||"—")}
                </td>;
              })}
            </tr>;
          })}</tbody>
        </table>
      </div>
    </div>
  </div>;
}

function AddPlotModal({onClose}){
  const [sel,setSel]=useState({gov:"",dist:"",village:"",basin:"",hood:"",plot:"",key:""});
  const [msg,setMsg]=useState("");
  const sSel=(k,v)=>{const n={...sel,[k]:v};if(k==="gov"){n.dist="";n.village="";n.basin="";n.hood="";}if(k==="dist"){n.village="";n.basin="";n.hood="";}if(k==="village"){n.basin="";n.hood="";}if(k==="basin"){n.hood="";}setSel(n);};
  const gi=HG.findIndex(g=>g[0]===sel.gov);
  const aDists=gi>=0?HD.map((d,i)=>({i,n:d[0],c:d[1],g:d[2]})).filter(d=>d.g===gi).sort((a,b)=>a.c-b.c):[];
  const di=HD.findIndex(d=>d[0]===sel.dist&&d[2]===gi);
  const aVils=di>=0?HV.map((v,i)=>({i,n:v[0],c:v[1],d:v[2]})).filter(v=>v.d===di).sort((a,b)=>a.c-b.c):[];
  const vi=HV.findIndex(v=>v[0]===sel.village&&v[2]===di);
  const aBas=vi>=0?HB.map((b,i)=>({i,n:b[0],c:b[1],v:b[2]})).filter(b=>b.v===vi).sort((a,b)=>a.c-b.c):[];
  const bi2=aBas.find(b=>b.n===sel.basin);
  const aHoods=bi2?HH.filter(h=>h[2]===bi2.i).map((h,i)=>({i,n:h[0],c:h[1]})).sort((a,b)=>a.c-b.c):[];
  const selStyle={width:"100%",border:"1.5px solid #e2e8f0",borderRadius:9,padding:"10px 12px",fontSize:13,outline:"none",marginBottom:10,background:"white",cursor:"pointer"};
  const disStyle={...selStyle,opacity:0.45,cursor:"default",background:"#f8fafc"};
  const buildMsg=()=>{
    const parts=[];
    if(sel.gov)parts.push(`المحافظة: ${sel.gov}`);
    if(sel.dist)parts.push(`المديرية: ${sel.dist}`);
    if(sel.village)parts.push(`القرية: ${sel.village}`);
    if(sel.basin)parts.push(`الحوض: ${sel.basin}`);
    if(sel.hood)parts.push(`الحي: ${sel.hood}`);
    if(sel.plot)parts.push(`رقم القطعة: ${sel.plot}`);
    if(sel.key)parts.push(`مفتاح القطعة: ${sel.key}`);
    return `مرحبا، أرغب بإضافة قطعة أرض للبيع:\n\n${parts.join("\n")}`;
  };
  const sendWA=()=>{const m=encodeURIComponent(buildMsg());window.open(`https://wa.me/962778445424?text=${m}`,"_blank");};
  return <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.6)",backdropFilter:"blur(4px)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:200,padding:16}}>
    <div onClick={e=>e.stopPropagation()} style={{background:"white",borderRadius:16,width:"100%",maxWidth:480,maxHeight:"90vh",overflowY:"auto",boxShadow:"0 25px 50px rgba(0,0,0,0.25)"}}>
      <div style={{background:"linear-gradient(135deg,#16a34a,#15803d)",padding:"20px 24px",borderRadius:"16px 16px 0 0"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <h2 style={{fontSize:18,fontWeight:800,color:"white"}}>➕ أضف قطعة أرض للبيع</h2>
          <button onClick={onClose} style={{background:"rgba(255,255,255,0.2)",border:"none",borderRadius:"50%",width:30,height:30,color:"white",fontSize:16,cursor:"pointer"}}>✕</button>
        </div>
        <p style={{fontSize:12,color:"rgba(255,255,255,0.8)",marginTop:6}}>حدد موقع القطعة بالتسلسل ثم أرسل التفاصيل عبر واتساب</p>
      </div>
      <div style={{padding:"20px 24px"}}>
        <label style={{fontSize:12,fontWeight:700,color:"#374151",display:"block",marginBottom:4}}>🏛️ المحافظة <span style={{color:"#ef4444"}}>*</span></label>
        <select value={sel.gov} onChange={e=>sSel("gov",e.target.value)} style={selStyle}>
          <option value="">— اختر المحافظة —</option>
          {HG.map((g,i)=>({n:g[0],c:g[1],i})).sort((a,b)=>a.c-b.c).map(g=><option key={g.i} value={g.n}>{g.n} ({g.c})</option>)}
        </select>
        <label style={{fontSize:12,fontWeight:700,color:"#374151",display:"block",marginBottom:4}}>📍 المديرية <span style={{color:"#ef4444"}}>*</span></label>
        <select value={sel.dist} onChange={e=>sSel("dist",e.target.value)} disabled={!sel.gov} style={sel.gov?selStyle:disStyle}>
          <option value="">— اختر المديرية —</option>
          {aDists.map(d=><option key={d.i} value={d.n}>{d.n} ({d.c})</option>)}
        </select>
        <label style={{fontSize:12,fontWeight:700,color:"#374151",display:"block",marginBottom:4}}>🏘️ القرية <span style={{color:"#ef4444"}}>*</span></label>
        <select value={sel.village} onChange={e=>sSel("village",e.target.value)} disabled={!sel.dist} style={sel.dist?selStyle:disStyle}>
          <option value="">— اختر القرية —</option>
          {aVils.map(v=><option key={v.i} value={v.n}>{v.n} ({v.c})</option>)}
        </select>
        <label style={{fontSize:12,fontWeight:700,color:"#374151",display:"block",marginBottom:4}}>📐 الحوض <span style={{color:"#ef4444"}}>*</span></label>
        <select value={sel.basin} onChange={e=>sSel("basin",e.target.value)} disabled={!sel.village} style={sel.village?selStyle:disStyle}>
          <option value="">— اختر الحوض —</option>
          {aBas.map(b=><option key={b.i} value={b.n}>{b.n} ({b.c})</option>)}
        </select>
        {aHoods.length>0&&<><label style={{fontSize:12,fontWeight:700,color:"#374151",display:"block",marginBottom:4}}>🏠 الحي</label>
        <select value={sel.hood} onChange={e=>sSel("hood",e.target.value)} style={selStyle}>
          <option value="">— اختر الحي (اختياري) —</option>
          {aHoods.map(h=><option key={h.i} value={h.n}>{h.n} ({h.c})</option>)}
        </select></>}
        <label style={{fontSize:12,fontWeight:700,color:"#374151",display:"block",marginBottom:4}}>🔢 رقم القطعة</label>
        <input value={sel.plot} onChange={e=>setSel({...sel,plot:e.target.value})} placeholder="أدخل رقم القطعة" style={selStyle}/>
        <label style={{fontSize:12,fontWeight:700,color:"#374151",display:"block",marginBottom:4}}>🔑 مفتاح القطعة</label>
        <input value={sel.key} onChange={e=>setSel({...sel,key:e.target.value})} placeholder="أدخل مفتاح القطعة" style={selStyle}/>
        {sel.gov&&sel.dist&&sel.village&&sel.basin&&<div style={{background:"#f0fdf4",border:"1px solid #bbf7d0",borderRadius:10,padding:14,marginBottom:14}}>
          <div style={{fontSize:11,color:"#166534",fontWeight:700,marginBottom:6}}>📋 ملخص القطعة:</div>
          <div style={{fontSize:12,color:"#374151",lineHeight:2}}>
            {sel.gov} ← {sel.dist} ← {sel.village} ← {sel.basin}{sel.hood?` ← ${sel.hood}`:""}{sel.plot?` | قطعة: ${sel.plot}`:""}{sel.key?` | مفتاح: ${sel.key}`:""}
          </div>
        </div>}
        <button onClick={sendWA} disabled={!sel.gov||!sel.dist||!sel.village||!sel.basin} style={{width:"100%",padding:"13px",borderRadius:10,border:"none",background:sel.basin?"linear-gradient(135deg,#22c55e,#16a34a)":"#e2e8f0",color:sel.basin?"white":"#94a3b8",fontSize:14,fontWeight:700,cursor:sel.basin?"pointer":"default",transition:"all 0.2s"}}>
          📱 أرسل عبر واتساب
        </button>
        <p style={{fontSize:10,color:"#94a3b8",textAlign:"center",marginTop:10}}>سيتم إرسال تفاصيل القطعة إلى فريق أراضي الأردن عبر واتساب</p>
      </div>
    </div>
  </div>;
}

export default function JordanLand(){
  const [page,setPage]=useState("home");
  const [filters,setFilters]=useState({gov:"",dist:"",village:"",basin:"",hood:""});
  const [sort,setSort]=useState("area-desc");
  const [search,setSearch]=useState("");
  const [favs,setFavs]=useState([]);
  const [compIds,setCompIds]=useState([]);
  const [detail,setDetail]=useState(null);
  const [showComp,setShowComp]=useState(false);
  const [showFavs,setShowFavs]=useState(false);
  const [showAddPlot,setShowAddPlot]=useState(false);
  const [perPage,setPerPage]=useState(40);
  const listRef=useRef(null);
  const [uploadedImages,setUploadedImages]=useState({});
  const addImage=(lotId,dataUrl)=>setUploadedImages(prev=>({...prev,[lotId]:[...(prev[lotId]||[]),dataUrl]}));
  const removeImage=(lotId,idx)=>setUploadedImages(prev=>({...prev,[lotId]:(prev[lotId]||[]).filter((_,i)=>i!==idx)}));
  // Hero cascading search state
  const [heroSel,setHeroSel]=useState({gov:"",dist:"",village:"",basin:""});

  useEffect(()=>{
    if(page==="listings"&&listRef.current){listRef.current.scrollTop=0;}
    window.scrollTo(0,0);
  },[page,filters.gov]);

  const toggleFav=useCallback(id=>setFavs(p=>p.includes(id)?p.filter(x=>x!==id):[...p,id]),[]);
  const toggleComp=useCallback(id=>setCompIds(p=>p.includes(id)?p.filter(x=>x!==id):p.length<4?[...p,id]:p),[]);

  // Hierarchy-based cascading options
  const hGovs=useMemo(()=>HG.map((g,i)=>({idx:i,name:g[0],code:g[1]})).sort((a,b)=>a.code-b.code),[]);
  const hDists=useMemo(()=>{if(!filters.gov)return[];const gi=HG.findIndex(g=>g[0]===filters.gov);if(gi<0)return[];return HD.map((d,i)=>({idx:i,name:d[0],code:d[1],gi:d[2]})).filter(d=>d.gi===gi).sort((a,b)=>a.code-b.code);},[filters.gov]);
  const hVils=useMemo(()=>{if(!filters.dist)return[];const di=HD.findIndex(d=>d[0]===filters.dist&&(filters.gov?d[2]===HG.findIndex(g=>g[0]===filters.gov):true));if(di<0)return[];return HV.map((v,i)=>({idx:i,name:v[0],code:v[1],di:v[2]})).filter(v=>v.di===di).sort((a,b)=>a.code-b.code);},[filters.dist,filters.gov]);
  const hBasins=useMemo(()=>{if(!filters.village)return[];const vi=HV.findIndex(v=>{const di=HD.findIndex(d=>d[0]===filters.dist);return v[0]===filters.village&&v[2]===di;});if(vi<0)return[];return HB.map((b,i)=>({idx:i,name:b[0],code:b[1],vi:b[2]})).filter(b=>b.vi===vi).sort((a,b)=>a.code-b.code);},[filters.village,filters.dist]);
  const hHoods=useMemo(()=>{if(!filters.basin)return[];const matches=hBasins.filter(b=>b.name===filters.basin);if(!matches.length)return[];const bi=matches[0].idx;return HH.filter(h=>h[2]===bi).map((h,i)=>({idx:i,name:h[0],code:h[1]})).sort((a,b)=>a.code-b.code);},[filters.basin,hBasins]);
  // Hero cascading options
  const heroGovs=hGovs;
  const heroDists=useMemo(()=>{if(!heroSel.gov)return[];const gi=HG.findIndex(g=>g[0]===heroSel.gov);if(gi<0)return[];return HD.map((d,i)=>({idx:i,name:d[0],code:d[1],gi:d[2]})).filter(d=>d.gi===gi).sort((a,b)=>a.code-b.code);},[heroSel.gov]);
  const heroVils=useMemo(()=>{if(!heroSel.dist)return[];const di=HD.findIndex(d=>d[0]===heroSel.dist&&d[2]===HG.findIndex(g=>g[0]===heroSel.gov));if(di<0)return[];return HV.map((v,i)=>({idx:i,name:v[0],code:v[1],di:v[2]})).filter(v=>v.di===di).sort((a,b)=>a.code-b.code);},[heroSel.dist,heroSel.gov]);
  const heroBasins=useMemo(()=>{if(!heroSel.village)return[];const di=HD.findIndex(d=>d[0]===heroSel.dist);const vi=HV.findIndex(v=>v[0]===heroSel.village&&v[2]===di);if(vi<0)return[];return HB.filter(b=>b[2]===vi).map((b,i)=>({idx:i,name:b[0],code:b[1]})).sort((a,b)=>a.code-b.code);},[heroSel.village,heroSel.dist]);
  // Keep govs for govStats
  const govs=useMemo(()=>[...new Set(LOTS.map(l=>l.gov))].sort((a,b)=>a.localeCompare(b,"ar")),[]);

  const filtered=useMemo(()=>{
    let r=LOTS;
    if(search){const s=search.trim();r=r.filter(l=>l.gov.includes(s)||l.dist.includes(s)||l.village.includes(s)||l.basin.includes(s)||String(l.plot).includes(s)||l.gov.replace("محافظة ","").includes(s)||l.dist.replace("اراضي ","").replace("محافظة ","").includes(s));}
    if(filters.gov)r=r.filter(l=>l.gov===filters.gov);
    if(filters.dist)r=r.filter(l=>l.dist===filters.dist);
    if(filters.village)r=r.filter(l=>l.village===filters.village);
    if(filters.basin)r=r.filter(l=>l.basin===filters.basin);
    if(filters.hood)r=r.filter(l=>l.hood===filters.hood);
    const [key,dir]=sort.split("-");
    r=[...r].sort((a,b)=>{if(key==="gov"||key==="village")return dir==="asc"?String(a[key]).localeCompare(String(b[key]),"ar"):String(b[key]).localeCompare(String(a[key]),"ar");return dir==="asc"?(a[key]-b[key]):(b[key]-a[key]);});
    return r;
  },[filters,sort,search]);

  const shown=filtered.slice(0,perPage);
  const favLots=useMemo(()=>LOTS.filter(l=>favs.includes(l.id)),[favs]);
  const compLots=useMemo(()=>LOTS.filter(l=>compIds.includes(l.id)),[compIds]);

  const setFilter=(k,v)=>{
    const next={...filters,[k]:v};
    if(k==="gov"){next.dist="";next.village="";next.basin="";next.hood="";}
    if(k==="dist"){next.village="";next.basin="";next.hood="";}
    if(k==="village"){next.basin="";next.hood="";}
    if(k==="basin"){next.hood="";}
    setFilters(next);setPerPage(40);
  };
  const clearFilters=()=>{setFilters({gov:"",dist:"",village:"",basin:"",hood:""});setSearch("");setPerPage(40);};
  const activeCount=Object.values(filters).filter(Boolean).length+(search?1:0);
  const setHero=(k,v)=>{
    const next={...heroSel,[k]:v};
    if(k==="gov"){next.dist="";next.village="";next.basin="";}
    if(k==="dist"){next.village="";next.basin="";}
    if(k==="village"){next.basin="";}
    setHeroSel(next);
  };
  const heroSearch=()=>{
    const f={gov:heroSel.gov,dist:heroSel.dist,village:heroSel.village,basin:heroSel.basin,hood:""};
    setFilters(f);setSearch("");setPage("listings");
  };

  // Governorate stats
  const govStats=useMemo(()=>govs.map(g=>{const lots=LOTS.filter(l=>l.gov===g);return{name:g,count:lots.length,villages:[...new Set(lots.map(l=>l.village))]};}),[govs]);

  const Navbar=()=><nav style={{background:"linear-gradient(135deg,#1a1207,#0f172a)",padding:"0 20px",height:54,display:"flex",alignItems:"center",justifyContent:"space-between",position:"sticky",top:0,zIndex:50,borderBottom:"2px solid #d97706",flexShrink:0}}>
    <div onClick={()=>setPage("home")} style={{cursor:"pointer",display:"flex",alignItems:"center",gap:10}}>
      <div style={{width:34,height:34,borderRadius:9,background:"linear-gradient(135deg,#d97706,#b45309)",display:"flex",alignItems:"center",justifyContent:"center",color:"white",fontWeight:900,fontSize:14}}>JL</div>
      <span style={{fontSize:16,fontWeight:800,color:"#fbbf24"}}>أراضي الأردن</span>
      <span style={{fontSize:10,color:"#94a3b8",fontWeight:500}}>Jordan Land</span>
    </div>
    <div style={{display:"flex",gap:6}}>
      <button onClick={()=>setShowFavs(true)} style={{background:"rgba(255,255,255,0.1)",border:"none",borderRadius:7,padding:"5px 12px",color:"white",cursor:"pointer",fontSize:11,fontWeight:600,display:"flex",alignItems:"center",gap:3,position:"relative"}}>
        ❤️{favs.length>0&&<span style={{background:"#ef4444",color:"white",fontSize:8,fontWeight:800,borderRadius:10,padding:"0px 5px",marginRight:2}}>{favs.length}</span>}
      </button>
      {compIds.length>=2&&<button onClick={()=>setShowComp(true)} style={{background:"#3b82f6",border:"none",borderRadius:7,padding:"5px 12px",color:"white",cursor:"pointer",fontSize:11,fontWeight:600}}>⚖️ قارن ({compIds.length})</button>}
      <button onClick={()=>setShowAddPlot(true)} style={{background:"linear-gradient(135deg,#16a34a,#15803d)",border:"none",borderRadius:7,padding:"5px 14px",color:"white",cursor:"pointer",fontSize:11,fontWeight:700}}>➕ أضف قطعة</button>
      {page!=="listings"&&<button onClick={()=>setPage("listings")} style={{background:"linear-gradient(135deg,#d97706,#b45309)",border:"none",borderRadius:7,padding:"5px 16px",color:"white",cursor:"pointer",fontSize:11,fontWeight:700}}>تصفح الأراضي</button>}
    </div>
  </nav>;

  // ─── HOME ───
  if(page==="home")return <div dir="rtl" style={{fontFamily:"'Segoe UI','Noto Kufi Arabic',Tahoma,sans-serif",background:"#fafaf8",minHeight:"100vh"}}>
    <Navbar/>
    {/* Hero */}
    <div style={{background:"linear-gradient(135deg,#1a1207 0%,#0f172a 50%,#1a0e04 100%)",padding:"52px 24px 44px",position:"relative",overflow:"hidden"}}>
      <div style={{position:"absolute",top:-80,left:-80,width:300,height:300,border:"1px solid rgba(217,119,6,0.1)",borderRadius:"50%"}}/>
      <div style={{position:"absolute",bottom:-40,right:-40,width:200,height:200,border:"1px solid rgba(217,119,6,0.08)",borderRadius:"50%"}}/>
      <div style={{position:"relative",maxWidth:800,margin:"0 auto"}}>
        <div style={{fontSize:10,color:"#d97706",fontWeight:700,letterSpacing:3,marginBottom:10}}>JORDAN LAND</div>
        <h1 style={{fontSize:36,fontWeight:900,color:"white",lineHeight:1.3,marginBottom:6}}>أرضك في الأردن</h1>
        <h2 style={{fontSize:18,fontWeight:400,color:"#fbbf24",marginBottom:16}}>مئات قطع الأراضي المميزة في كافة المحافظات</h2>
        <p style={{fontSize:13,color:"#94a3b8",lineHeight:1.8,maxWidth:500,marginBottom:24}}>منصة متكاملة لبيع الأراضي في المملكة الأردنية الهاشمية. ابحث، قارن، واستثمر بثقة.</p>
        <div style={{background:"rgba(255,255,255,0.08)",backdropFilter:"blur(10px)",borderRadius:13,padding:16,border:"1px solid rgba(255,255,255,0.1)",maxWidth:560}}>
          <div style={{fontSize:12,color:"#fbbf24",fontWeight:700,marginBottom:12}}>🔍 ابحث عن قطعة أرض</div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
            <select value={heroSel.gov} onChange={e=>setHero("gov",e.target.value)} style={{background:"rgba(255,255,255,0.1)",color:heroSel.gov?"white":"#94a3b8",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,padding:"10px 10px",fontSize:12,outline:"none",cursor:"pointer"}}>
              <option value="" style={{color:"#333"}}>🏛️ المحافظة</option>
              {heroGovs.map(g=><option key={g.idx} value={g.name} style={{color:"#333"}}>{g.name} ({g.code})</option>)}
            </select>
            <select value={heroSel.dist} onChange={e=>setHero("dist",e.target.value)} disabled={!heroSel.gov} style={{background:"rgba(255,255,255,0.1)",color:heroSel.dist?"white":"#94a3b8",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,padding:"10px 10px",fontSize:12,outline:"none",cursor:"pointer",opacity:heroSel.gov?1:0.4}}>
              <option value="" style={{color:"#333"}}>📍 المديرية</option>
              {heroDists.map(d=><option key={d.idx} value={d.name} style={{color:"#333"}}>{d.name} ({d.code})</option>)}
            </select>
            <select value={heroSel.village} onChange={e=>setHero("village",e.target.value)} disabled={!heroSel.dist} style={{background:"rgba(255,255,255,0.1)",color:heroSel.village?"white":"#94a3b8",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,padding:"10px 10px",fontSize:12,outline:"none",cursor:"pointer",opacity:heroSel.dist?1:0.4}}>
              <option value="" style={{color:"#333"}}>🏘️ القرية</option>
              {heroVils.map(v=><option key={v.idx} value={v.name} style={{color:"#333"}}>{v.name} ({v.code})</option>)}
            </select>
            <select value={heroSel.basin} onChange={e=>setHero("basin",e.target.value)} disabled={!heroSel.village} style={{background:"rgba(255,255,255,0.1)",color:heroSel.basin?"white":"#94a3b8",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,padding:"10px 10px",fontSize:12,outline:"none",cursor:"pointer",opacity:heroSel.village?1:0.4}}>
              <option value="" style={{color:"#333"}}>📐 الحوض</option>
              {heroBasins.map(b=><option key={b.idx} value={b.name} style={{color:"#333"}}>{b.name} ({b.code})</option>)}
            </select>
          </div>
          <button onClick={heroSearch} disabled={!heroSel.gov} style={{width:"100%",background:heroSel.gov?"linear-gradient(135deg,#d97706,#b45309)":"rgba(255,255,255,0.1)",color:heroSel.gov?"white":"#64748b",borderRadius:9,padding:"11px 22px",fontSize:13,fontWeight:700,border:"none",cursor:heroSel.gov?"pointer":"default",transition:"all 0.2s"}}>🔍 بحث عن القطع المتوفرة</button>
        </div>
        <div style={{display:"flex",gap:36,marginTop:28}}>
          {[[LOTS.length,"قطعة أرض"],[govs.length,"محافظات"],[LOTS.filter(l=>l.mapUrl).length,"موقع على الخريطة"],[LOTS.filter(l=>l.pic).length,"صورة متوفرة"]].map(([n,l],i)=>
            <div key={i}><div style={{fontSize:24,fontWeight:900,color:"#fbbf24"}}>{n}</div><div style={{fontSize:10,color:"#94a3b8"}}>{l}</div></div>
          )}
        </div>
      </div>
    </div>
    {/* Governorate Grid */}
    <div style={{maxWidth:960,margin:"0 auto",padding:"44px 20px"}}>
      <h2 style={{fontSize:20,fontWeight:800,color:"#1e293b",marginBottom:4}}>تصفح حسب المحافظة</h2>
      <p style={{fontSize:12,color:"#64748b",marginBottom:20}}>اختر المحافظة لعرض القطع المتوفرة</p>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280,1fr))",gap:12}}>
        {govStats.map(g=>{const c=gc(g.name);return <div key={g.name} onClick={()=>{setFilter("gov",g.name);setPage("listings")}} style={{background:`linear-gradient(135deg,${c.bg},white)`,borderRadius:13,padding:"18px 20px",cursor:"pointer",border:`1.5px solid ${c.br}40`,transition:"all 0.2s",boxShadow:"0 2px 8px rgba(0,0,0,0.04)"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
            <div style={{fontSize:17,fontWeight:800,color:"#1e293b"}}>{g.name.replace("محافظة ","")}</div>
            <div style={{background:c.dk,color:"white",fontSize:11.5,fontWeight:700,padding:"3px 12px",borderRadius:18}}>{g.count}</div>
          </div>
          <div style={{fontSize:10.5,color:"#64748b",lineHeight:1.7,marginBottom:6}}>{g.villages.slice(0,4).join("، ")}{g.villages.length>4?` +${g.villages.length-4}`:""}</div>
          <div style={{fontSize:10,color:c.tx,fontWeight:600}}>{g.count} قطعة أرض متوفرة</div>
        </div>;})}
      </div>
    </div>
    {/* Trust */}
    <div style={{background:"white",padding:"44px 20px",borderTop:"1px solid #e2e8f0"}}>
      <div style={{maxWidth:960,margin:"0 auto"}}>
        <h2 style={{fontSize:20,fontWeight:800,color:"#1e293b",marginBottom:20,textAlign:"center"}}>لماذا أراضي الأردن؟</h2>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200,1fr))",gap:16}}>
          {[["📋","بيانات رسمية","جميع البيانات مطابقة لسجلات دائرة الأراضي"],["🗺️","مواقع على الخريطة","روابط مباشرة لخرائط جوجل للقطع المتوفرة"],["🏞️","صور القطع","صور فعلية للقطع المتاحة للبيع"],["📞","دعم مباشر","تواصل عبر الهاتف أو واتساب"]].map(([icon,title,desc],i)=>
            <div key={i} style={{textAlign:"center",padding:"22px 14px",background:"#fafaf8",borderRadius:13,border:"1px solid #e2e8f0"}}>
              <div style={{fontSize:28,marginBottom:10}}>{icon}</div>
              <div style={{fontSize:14,fontWeight:700,color:"#1e293b",marginBottom:4}}>{title}</div>
              <div style={{fontSize:11.5,color:"#64748b",lineHeight:1.6}}>{desc}</div>
            </div>
          )}
        </div>
      </div>
    </div>
    <div style={{background:"#0f172a",padding:"28px 20px",textAlign:"center"}}>
      <div style={{fontSize:13,fontWeight:700,color:"#fbbf24",marginBottom:6}}>أراضي الأردن — Jordan Land</div>
      <div style={{fontSize:11,color:"#64748b"}}>جميع الحقوق محفوظة © 2026</div>
    </div>
    {showFavs&&<FavModal lots={favLots} onClose={()=>setShowFavs(false)} onDetail={l=>{setDetail(l);setShowFavs(false)}} toggleFav={toggleFav}/>}
    {showAddPlot&&<AddPlotModal onClose={()=>setShowAddPlot(false)}/>}
    <DetailModal lot={detail} onClose={()=>setDetail(null)} images={uploadedImages} addImage={addImage} removeImage={removeImage}/>
  </div>;

  // ─── LISTINGS ───
  return <div dir="rtl" style={{fontFamily:"'Segoe UI','Noto Kufi Arabic',Tahoma,sans-serif",background:"#fafaf8",minHeight:"100vh",display:"flex",flexDirection:"column"}}>
    <Navbar/>
    <div style={{display:"flex",flex:1,overflow:"hidden"}}>
      {/* Sidebar */}
      <div style={{width:260,background:"white",borderLeft:"1px solid #e2e8f0",padding:"16px 14px",overflowY:"auto",flexShrink:0,display:"flex",flexDirection:"column"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:14}}>
          <h3 style={{fontSize:14,fontWeight:800,color:"#1e293b"}}>🔍 البحث المتقدم</h3>
          {activeCount>0&&<button onClick={clearFilters} style={{background:"#fef2f2",border:"none",borderRadius:5,padding:"3px 8px",color:"#ef4444",cursor:"pointer",fontSize:10,fontWeight:600}}>مسح</button>}
        </div>
        <input value={search} onChange={e=>{setSearch(e.target.value);setPerPage(40)}} placeholder="بحث نصي سريع..." style={{width:"100%",border:"1.5px solid #e2e8f0",borderRadius:9,padding:"9px 11px",fontSize:12,outline:"none",boxSizing:"border-box",marginBottom:12}}/>
        <FilterSelect label="المحافظة" icon="🏛️" value={filters.gov} options={hGovs.map(g=>g.name)} codeMap={Object.fromEntries(hGovs.map(g=>[g.name,g.code]))} onChange={v=>setFilter("gov",v)} count={filters.gov?LOTS.filter(l=>l.gov===filters.gov).length:LOTS.length}/>
        <FilterSelect label="المديرية" icon="📍" value={filters.dist} options={hDists.map(d=>d.name)} codeMap={Object.fromEntries(hDists.map(d=>[d.name,d.code]))} onChange={v=>setFilter("dist",v)} disabled={!filters.gov}/>
        <FilterSelect label="القرية" icon="🏘️" value={filters.village} options={hVils.map(v=>v.name)} codeMap={Object.fromEntries(hVils.map(v=>[v.name,v.code]))} onChange={v=>setFilter("village",v)} disabled={!filters.dist}/>
        <FilterSelect label="الحوض" icon="📐" value={filters.basin} options={hBasins.map(b=>b.name)} codeMap={Object.fromEntries(hBasins.map(b=>[b.name,b.code]))} onChange={v=>setFilter("basin",v)} disabled={!filters.village}/>
        {hHoods.length>0&&<FilterSelect label="الحي" icon="🏠" value={filters.hood} options={hHoods.map(h=>h.name)} codeMap={Object.fromEntries(hHoods.map(h=>[h.name,h.code]))} onChange={v=>setFilter("hood",v)} disabled={!filters.basin}/>}
        {activeCount>0&&<div style={{display:"flex",flexWrap:"wrap",gap:4,marginTop:8}}>
          {Object.entries(filters).filter(([,v])=>v).map(([k,v])=>
            <span key={k} style={{background:"#fef3c7",color:"#92400e",fontSize:9,fontWeight:600,padding:"2px 7px",borderRadius:5,display:"flex",alignItems:"center",gap:3}}>
              {v.replace("محافظة ","").replace("اراضي ","")}<span onClick={()=>setFilter(k,"")} style={{cursor:"pointer",fontWeight:800}}>✕</span>
            </span>
          )}
        </div>}
        <div style={{marginTop:"auto",paddingTop:16,borderTop:"1px solid #f1f5f9"}}>
          <div style={{background:"#f8fafc",borderRadius:9,padding:12}}>
            <div style={{fontSize:10,color:"#94a3b8"}}>نتائج البحث</div>
            <div style={{fontSize:20,fontWeight:800,color:"#1e293b"}}>{filtered.length} <span style={{fontSize:12,fontWeight:400,color:"#64748b"}}>/ {LOTS.length}</span></div>
          </div>
        </div>
      </div>
      {/* Main */}
      <div ref={listRef} style={{flex:1,overflowY:"auto",padding:20}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16,flexWrap:"wrap",gap:10}}>
          <div>
            <h1 style={{fontSize:18,fontWeight:800,color:"#1e293b",marginBottom:1}}>الأراضي المتاحة</h1>
            <p style={{fontSize:12,color:"#64748b"}}>عرض {Math.min(perPage,filtered.length)} من {filtered.length} قطعة</p>
          </div>
          <select value={sort} onChange={e=>setSort(e.target.value)} style={{border:"1.5px solid #e2e8f0",borderRadius:7,padding:"7px 10px",fontSize:11.5,fontWeight:600,background:"white",cursor:"pointer"}}>
            <option value="area-asc">المساحة ↑</option>
            <option value="area-desc">المساحة ↓</option>
            <option value="sn-asc">الرقم التسلسلي ↑</option>
            <option value="sn-desc">الرقم التسلسلي ↓</option>
            <option value="gov-asc">المحافظة</option>
          </select>
        </div>
        {filtered.length===0?
          <div style={{textAlign:"center",padding:"60px 20px"}}>
            <div style={{fontSize:44,marginBottom:14}}>🏜️</div>
            <h3 style={{fontSize:16,fontWeight:700,color:"#1e293b",marginBottom:6}}>لا توجد نتائج</h3>
            <p style={{fontSize:12,color:"#64748b",marginBottom:16}}>حاول تعديل معايير البحث</p>
            <button onClick={clearFilters} style={{background:"linear-gradient(135deg,#d97706,#b45309)",color:"white",border:"none",borderRadius:9,padding:"9px 20px",fontSize:12,fontWeight:700,cursor:"pointer"}}>عرض الكل</button>
          </div>
        :<>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(270,1fr))",gap:14}}>
            {shown.map(lot=><LotCard key={lot.id} lot={lot} isFav={favs.includes(lot.id)} toggleFav={toggleFav} isComp={compIds.includes(lot.id)} toggleComp={toggleComp} onDetail={setDetail} uploadedImg={uploadedImages[lot.id]?uploadedImages[lot.id][0]:null}/>)}
          </div>
          {perPage<filtered.length&&<div style={{textAlign:"center",marginTop:24}}>
            <button onClick={()=>setPerPage(p=>p+40)} style={{background:"white",border:"1.5px solid #d97706",borderRadius:10,padding:"11px 32px",fontSize:13,fontWeight:700,color:"#b45309",cursor:"pointer"}}>
              عرض المزيد ({filtered.length-perPage} متبقية)
            </button>
          </div>}
        </>}
      </div>
    </div>
    {/* Compare bar */}
    {compIds.length>=1&&!showComp&&<div style={{position:"fixed",bottom:16,left:"50%",transform:"translateX(-50%)",background:"#1e293b",borderRadius:12,padding:"10px 20px",display:"flex",alignItems:"center",gap:14,boxShadow:"0 10px 30px rgba(0,0,0,0.3)",zIndex:100}}>
      <span style={{color:"white",fontSize:12,fontWeight:600}}>⚖️ {compIds.length} للمقارنة</span>
      {compIds.length>=2&&<button onClick={()=>setShowComp(true)} style={{background:"#3b82f6",color:"white",border:"none",borderRadius:7,padding:"7px 14px",fontSize:11,fontWeight:700,cursor:"pointer"}}>قارن</button>}
      <button onClick={()=>setCompIds([])} style={{background:"rgba(255,255,255,0.1)",color:"#94a3b8",border:"none",borderRadius:7,padding:"7px 10px",fontSize:10,cursor:"pointer"}}>✕</button>
    </div>}
    <a href="https://wa.me/962778445424" target="_blank" rel="noreferrer" style={{position:"fixed",bottom:16,left:16,width:52,height:52,borderRadius:"50%",background:"#25D366",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"0 4px 16px rgba(37,211,102,0.4)",zIndex:90,textDecoration:"none",fontSize:24}}>💬</a>
    <DetailModal lot={detail} onClose={()=>setDetail(null)} images={uploadedImages} addImage={addImage} removeImage={removeImage}/>
    {showComp&&<CompareModal lots={compLots} onClose={()=>setShowComp(false)}/>}
    {showFavs&&<FavModal lots={favLots} onClose={()=>setShowFavs(false)} onDetail={l=>{setDetail(l);setShowFavs(false)}} toggleFav={toggleFav}/>}
    {showAddPlot&&<AddPlotModal onClose={()=>setShowAddPlot(false)}/>}
  </div>;
}

function FavModal({lots,onClose,onDetail,toggleFav}){
  return <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.5)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
    <div onClick={e=>e.stopPropagation()} dir="rtl" style={{background:"white",borderRadius:18,maxWidth:500,width:"100%",maxHeight:"80vh",overflow:"auto",padding:24}}>
      <h2 style={{fontSize:18,fontWeight:800,marginBottom:14}}>❤️ المفضلة ({lots.length})</h2>
      {lots.length===0?<p style={{color:"#94a3b8",fontSize:12}}>لم تضف أي قطع بعد</p>:
        lots.map(l=><div key={l.id} onClick={()=>onDetail(l)} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 0",borderBottom:"1px solid #f1f5f9",cursor:"pointer"}}>
          <div>
            <div style={{fontSize:13,fontWeight:700}}>قطعة {l.plot} — {l.village}</div>
            <div style={{fontSize:11,color:"#64748b"}}>{l.gov.replace("محافظة ","")} | {fmt(l.area)} م² | {l.adminPrice||"—"}</div>
          </div>
          <button onClick={e=>{e.stopPropagation();toggleFav(l.id)}} style={{background:"#fef2f2",border:"none",borderRadius:7,padding:"5px 10px",color:"#ef4444",cursor:"pointer",fontSize:10,fontWeight:600}}>إزالة</button>
        </div>)
      }
      <button onClick={onClose} style={{marginTop:14,width:"100%",background:"#f1f5f9",border:"none",borderRadius:9,padding:10,fontWeight:600,cursor:"pointer",fontSize:12}}>إغلاق</button>
    </div>
  </div>;
}
